// Builds a portable, local-only report. Keeping the shape pure makes the export
// easy to verify without a DOM.
export function reportDocument(quote, result) {
  return {
    product: "Quote Margin Check",
    exported_at: new Date().toISOString(),
    inputs: quote,
    result,
    disclaimer: "Arithmetic only; not tax, financial, or business advice. Review and verify every assumption before relying on this output.",
  };
}

review.mjs.text:
import { targetHoursBudget } from "./calc.mjs";

// Transparent pre-send observations for a quote. These are not pricing advice
// or a profitability determination; they point back to the supplied figures.

export function reviewQuote(quote, report) {
  const checks = [];
  const hiddenHours = quote.admin_hours + quote.revision_hours;
  const hoursBudget = targetHoursBudget(quote, report);

  if (report.direct_costs > quote.price) {
    checks.push({ level: "attention", title: "Direct costs exceed the quoted price", detail: `The supplied direct costs are ${quote.currency} ${report.direct_costs.toFixed(2)} against ${quote.currency} ${quote.price.toFixed(2)}.` });
  } else if (report.direct_costs === quote.price) {
    checks.push({ level: "attention", title: "Direct costs use the entire quoted price", detail: `The supplied direct costs use all ${quote.currency} ${quote.price.toFixed(2)} of the quoted price, leaving nothing after direct costs.` });
  }
  if (report.gap_to_target < 0) {
    checks.push({ level: "attention", title: "The quote is below the supplied target", detail: `The arithmetic gap is ${quote.currency} ${Math.abs(report.gap_to_target).toFixed(2)} below the target price.` });
  }
  if (hiddenHours > 0) {
    checks.push({ level: "note", title: "Hidden time is included", detail: `${hiddenHours.toFixed(2)} hours of admin and revisions are included in the effective rate.` });
  }
  if (report.hidden_time_percent >= 25) {
    checks.push({ level: "attention", title: "Hidden time is at least a quarter of the work", detail: `${report.hidden_time_percent.toFixed(1)}% of the supplied hours are admin or revisions. Confirm the scope, revision limit, and client communication time before sending.` });
  }
  if (quote.revision_hours === 0) {
    checks.push({ level: "note", title: "No revision hours are included", detail: "Confirm that the quote scope and revision assumptions match the work you expect to deliver." });
  }
  // Same inequality as "below the supplied target" (price < hours × rate +
  // costs), so this stays a note that names the hour figure rather than a
  // second attention flag on the same arithmetic.
  //
  // The budget is a signed figure: when direct costs exceed the price it goes
  // negative, and `hours_at_target` in discountAskScenarios already treats
  // that as "not applicable" rather than a number. Saying "the quote supports
  // -4.00 total hours" reads as a quantity of hours, which is not what a
  // negative there means — there is no budget to spend, because the quote is
  // short before anyone works an hour.
  if (report.cost_coverage <= 0) {
    const costs = `${quote.currency} ${report.direct_costs.toFixed(2)}`;
    const price = `${quote.currency} ${quote.price.toFixed(2)}`;
    const relation = report.cost_coverage < 0
      ? `direct costs of ${costs} exceed the ${price} quoted price by ${quote.currency} ${Math.abs(report.cost_coverage).toFixed(2)}`
      : `direct costs of ${costs} use the whole ${price} quoted price`;
    checks.push({ level: "note", title: "Target-rate hours budget", detail: `There is no time budget at the target rate: ${relation}, so the ${report.total_hours.toFixed(2)} estimated hours are unpaid at any rate.` });
  } else if (hoursBudget < report.total_hours) {
    checks.push({ level: "note", title: "Target-rate hours budget", detail: `At the supplied target rate, the quote supports ${hoursBudget.toFixed(2)} total hours; the estimate is ${report.total_hours.toFixed(2)}.` });
  } else {
    checks.push({ level: "note", title: "Target-rate hours budget", detail: `The supplied price supports up to ${hoursBudget.toFixed(2)} total hours after direct costs at the target rate.` });
  }
  if (!checks.some((check) => check.level === "attention")) {
    checks.push({ level: "clear", title: "No review flags from these inputs", detail: "Review the scope, assumptions, and arithmetic before relying on this result." });
  }
  return checks;
}

// A workflow prompt, not a recommendation: the quote owner chooses what to do
// after seeing the arithmetic observations above.
export function reviewDecision(report, quote) {
  const checks = reviewQuote(quote, report);
  const attentionCount = checks.filter((check) => check.level === "attention").length;
  if (attentionCount > 0) {
    return {
      tone: "attention",
      title: "Review the flags before deciding",
      detail: `${attentionCount} arithmetic ${attentionCount === 1 ? "flag needs" : "flags need"} your attention. The choice remains yours.`,
    };
  }
  return {
    tone: "clear",
    title: "No arithmetic flags found",
    detail: "You can record your own next step after checking the scope and assumptions.",
  };
}

summary.mjs.text:
// Plain-text handoff for a quote review. It contains supplied figures and
// derived arithmetic, but deliberately avoids presenting a profitability or
// pricing recommendation.

export function formatReviewSummary(quote, report, checks, decision = null, extras = {}) {
  const money = (value) => `${quote.currency} ${value.toFixed(2)}`;
  const flags = checks
    .filter((check) => check.level === "attention")
    .map((check) => `- ${check.title}: ${check.detail}`);
  const nextStep = decision?.title
    ? [`Next-step prompt: ${decision.title}`, ""]
    : [];
  const overrunRows = Array.isArray(extras.overrunRows) ? extras.overrunRows : [];
  const overrun = overrunRows.length
    ? [
        "Time-overrun scenarios (not a prediction):",
        ...overrunRows.map((scenario) => `+${scenario.percent}% time: ${scenario.total_hours.toFixed(2)} hours, ${money(scenario.effective_hourly_rate)}/hour, gap ${money(scenario.gap_to_target)}`),
        "",
      ]
    : [];

  return [
    "QUOTE MARGIN CHECK",
    "Arithmetic review for discussion, not pricing or financial advice.",
    ...nextStep,
    `Quoted price: ${money(quote.price)}`,
    `Total working hours: ${report.total_hours.toFixed(2)} (${report.hidden_hours.toFixed(2)} admin/revision hours)`,
    `Direct costs: ${money(report.direct_costs)}`,
    `Effective hourly rate: ${money(report.effective_hourly_rate)}/hour`,
    `Target hourly rate supplied: ${money(quote.target_hourly_rate)}/hour`,
    `Price at target rate: ${money(report.target_price)}`,
    `Gap to target price: ${money(report.gap_to_target)}`,
    `Left after direct costs: ${money(report.cost_coverage)}`,
    `Minimum increase to reach target: ${money(report.minimum_price_adjustment)}`,
    "",
    ...overrun,
    "Review observations:",
    ...(flags.length ? flags : ["- No arithmetic attention flags from these inputs."]),
    "",
    "Review the scope, assumptions, and arithmetic before relying on this output.",
  ].join("\n");
}

usage.mjs.text:
// Local-first, aggregate-only usage counting, per portfolio/usage/usage.yaml:
// count events, never people. No IDs, no IPs, no content — just an event
// name and a day, kept in this browser's own localStorage. Nothing is sent
// anywhere; there is no server for it to go to. Off-switchable, and honors
// Do Not Track / Global Privacy Control automatically.

const STORAGE_KEY = "quote-margin-check:usage-events";
const OPT_OUT_KEY = "quote-margin-check:usage-opt-out";

function hasStorage() {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function honorsBrowserSignal() {
  try {
    return navigator?.doNotTrack === "1" || navigator?.globalPrivacyControl === true;
  } catch {
    return false;
  }
}

export function isUsageCountingEnabled() {
  if (!hasStorage()) return false;
  if (honorsBrowserSignal()) return false;
  try {
    return localStorage.getItem(OPT_OUT_KEY) !== "1";
  } catch {
    return false;
  }
}

export function setUsageCountingEnabled(enabled) {
  if (!hasStorage()) return;
  try {
    if (enabled) localStorage.removeItem(OPT_OUT_KEY);
    else localStorage.setItem(OPT_OUT_KEY, "1");
  } catch {
    // storage unavailable (private mode, quota) — nothing to do
  }
}

/** Records that `eventName` happened today. Aggregate count only; no payload beyond the event name and the day. */
export function recordEvent(eventName) {
  if (!isUsageCountingEnabled()) return;
  try {
    const day = new Date().toISOString().slice(0, 10);
    const raw = localStorage.getItem(STORAGE_KEY);
    const events = raw ? JSON.parse(raw) : {};
    const key = `${eventName}:${day}`;
    events[key] = (events[key] || 0) + 1;
    localStorage.setItem(STORAGE_KEY, JSON.stringify(events));
  } catch {
    // storage unavailable — counting is best-effort only
  }
}

/**
 * Wraps `recordEvent` so a live-updating form counts *reports*, not keystrokes.
 *
 * The form recomputes on every `input` event, so calling `recordEvent` straight
 * from the render path counts one "report" per character typed — typing `4200`
 * into the price field logs four. And because the page opens pre-filled with a
 * worked example, the first render counted a bare page view as a report too.
 *
 * That inflates the only signal this portfolio uses to judge whether a tool is
 * used at all, and inflates it most for the users who fiddle with their numbers
 * the longest, which is exactly backwards.
 *
 * So: `seed()` the pre-filled first render without counting it, then wait until
 * input has settled (`delayMs` with no further calls) and count once — and only
 * if the settled quote actually differs from the last one counted, so tabbing
 * through fields or retyping the same figure doesn't add a second report.
 * `drop()` cancels a pending count when the form goes invalid mid-edit.
 *
 * Timer functions are injected so this is testable without real waiting.
 */
export function createReportCounter({
  record = recordEvent,
  setTimer = (fn, ms) => setTimeout(fn, ms),
  clearTimer = (id) => clearTimeout(id),
  delayMs = 1200,
  eventName = "report_generated",
} = {}) {
  let pending = null;
  let lastCounted = null;

  function cancel() {
    if (pending !== null) {
      clearTimer(pending);
      pending = null;
    }
  }

  return {
    /** Marks a signature as already-seen without counting it (the pre-filled first render). */
    seed(signature) {
      cancel();
      lastCounted = signature;
    },
    /** Cancels any pending count — the form is mid-edit and currently invalid. */
    drop: cancel,
    /** Counts one report once `signature` settles, if it differs from the last counted. */
    count(signature) {
      cancel();
      pending = setTimer(() => {
        pending = null;
        if (signature === lastCounted) return;
        lastCounted = signature;
        record(eventName);
      }, delayMs);
    },
  };
}

/** Returns the raw local event counts, for the user's own inspection. */
export function readLocalUsage() {
  if (!hasStorage()) return {};
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : {};
  } catch {
    return {};
  }
}
